import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const sha=b=>createHash('sha256').update(b).digest('hex');export const FOUNDER_LEGACY_ROUTE_RECORD="content/production-closure/live-customer-commercial-convergence/final-unified-production-r1/FOUNDER-LEGACY-ROUTE-COMPATIBILITY-R1.json";const recordSHA="8054652e8ca5d83fe53f1674e48c9096c758338f831aa5dd5518d9abeaca95f8";
export function validateFounderLegacyRoutes({readFile=p=>fs.readFileSync(p),recordBytes=readFile(FOUNDER_LEGACY_ROUTE_RECORD)}={}){assert.equal(sha(recordBytes),recordSHA,'FOUNDER_LEGACY_RECORD_DRIFT');const r=JSON.parse(recordBytes);assert.equal(r.schema,'FOUNDER_LEGACY_ROUTE_COMPATIBILITY_R1');assert.equal(r.predecessorHEAD,'f475ce1ae01b4138d368d52ee69d3906e2f9acca');assert.deepEqual(r.changes.map(x=>x.path),['_redirects','assets/js/explore-about-compat.js','scripts/lib/world-contrast-r3-source-successor.mjs']);for(const v of Object.values(r.boundaries))assert.equal(v,false);for(const x of r.parents)assert.equal(sha(readFile(x.path)),x.sha256,'FOUNDER_LEGACY_PARENT_DRIFT:'+x.path);for(const x of r.changes){assert.equal(sha(readFile(x.path)),x.sha256,'FOUNDER_LEGACY_PHYSICAL_DRIFT:'+x.path);assert.equal(sha(Buffer.from(x.previousBytesBase64,'base64')),x.previousSHA256,'FOUNDER_LEGACY_PREDECESSOR:'+x.path)}const [redirects,,hook]=r.changes;let expected=Buffer.from(redirects.previousBytesBase64,'base64').toString();assert.equal(redirects.pairs.length,9);for(const [before,after]of redirects.pairs){assert.equal(expected.split(before).length,2);expected=expected.replace(before,after)}assert.equal(readFile(redirects.path).toString(),expected,'FOUNDER_LEGACY_EXACT_RULES');const prior=Buffer.from(hook.previousBytesBase64,'base64'),current=readFile(hook.path).toString();assert(current.startsWith(hook.exactImport));const body=current.slice(hook.exactImport.length);assert.equal(body.split(hook.entry+hook.addition).length,2);assert(Buffer.from(body.replace(hook.entry+hook.addition,hook.entry)).equals(prior),'FOUNDER_LEGACY_WORLD_ASSERTIONS_CHANGED');return r;}
export function founderLegacyRoutePredecessor(path,bytes,options={}){if(EXACT3_CI_PATHS.includes(path))return exact3CiPredecessor(path,bytes,options);if(!['_redirects','assets/js/explore-about-compat.js'].includes(path))return bytes;const r=validateFounderLegacyRoutes(options),row=r.changes.find(x=>x.path===path),digest=sha(Buffer.from(bytes));assert([row.sha256,row.previousSHA256].includes(digest),'FOUNDER_LEGACY_INPUT_DRIFT');return digest===row.previousSHA256?bytes:Buffer.from(row.previousBytesBase64,'base64');}

// Strict CI-only descendant: original value assertions stay bound to their exact registered predecessor.
const EXACT3_CI_BYTES="",EXACT3_CI_SHA="5f4db8ba2292a54fe3bce7d8ced26db14fc10ba37b9d19ef28d3f33867ef8ae3",EXACT3_CI_PATHS=["scripts/check-books-1-6-publication-commerce.mjs","scripts/check-figure-story-deck-r1.mjs","scripts/check-pja-w1-blueprint-led-knowledge.mjs"];
export function validateExact3CiConsumers({readFile=p=>fs.readFileSync(p),recordBytes=Buffer.from(EXACT3_CI_BYTES,'base64')}={}){assert.equal(sha(recordBytes),EXACT3_CI_SHA,'EXACT3_CI_RECORD_DRIFT');const r=JSON.parse(recordBytes);assert.equal(r.schema,'EXACT3_CI_CONSUMER_SUCCESSOR_R1');assert.equal(r.predecessorHEAD,'c89bb672f62bba81edbdf253b3f11d65731b5ab1');assert.deepEqual(r.changes.map(x=>x.path),EXACT3_CI_PATHS);for(const v of Object.values(r.boundaries))assert.equal(v,false);validateFounderLegacyRoutes({readFile});for(const x of r.changes){assert.equal(sha(readFile(x.path)),x.sha256,'EXACT3_CI_PHYSICAL_DRIFT:'+x.path);assert.equal(sha(Buffer.from(x.previousBytesBase64,'base64')),x.previousSHA256,'EXACT3_CI_PREDECESSOR:'+x.path)}return r;}
function exact3CiPredecessor(path,bytes,options){const r=validateExact3CiConsumers(options),row=r.changes.find(x=>x.path===path),digest=sha(Buffer.from(bytes));assert(row);assert([row.sha256,row.previousSHA256].includes(digest),'EXACT3_CI_INPUT_DRIFT');return digest===row.previousSHA256?bytes:Buffer.from(row.previousBytesBase64,'base64');}
